package runtime_test

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
	"time"

	"github.com/ACaccel/lcm/internal/execx"
	rt "github.com/ACaccel/lcm/internal/runtime"
)

// These tests drive real systemd and Docker. They are opt-in
// (LCM_IT_SYSTEMD=1, LCM_IT_DOCKER=1) and only ever touch throwaway
// resources named lcm-it-<random> that they create and remove themselves.

// tool builds a command for the system tools these tests drive; every
// argument is a constant or a name generated by the test.
func tool(name string, args ...string) *exec.Cmd {
	return exec.Command(name, args...) //nolint:gosec // arguments are test-controlled
}

func randomName(t *testing.T) string {
	t.Helper()
	var b [4]byte
	if _, err := rand.Read(b[:]); err != nil {
		t.Fatal(err)
	}
	return "lcm-it-" + hex.EncodeToString(b[:])
}

// waitState polls until the adapter reports want. Real processes change
// state asynchronously, so there is no clock to inject here.
func waitState(t *testing.T, status func() rt.Status, want rt.State) {
	t.Helper()
	deadline := time.Now().Add(20 * time.Second)
	var last rt.Status
	for time.Now().Before(deadline) {
		last = status()
		if last.State == want {
			return
		}
		time.Sleep(100 * time.Millisecond)
	}
	t.Fatalf("state never became %s; last %+v", want, last)
}

func TestRealSystemdUserScope(t *testing.T) {
	if os.Getenv("LCM_IT_SYSTEMD") != "1" {
		t.Skip("set LCM_IT_SYSTEMD=1 to run against systemd --user")
	}
	if err := tool("systemctl", "--user", "show-environment").Run(); err != nil {
		t.Skipf("systemd --user is not available: %v", err)
	}
	home, err := os.UserHomeDir()
	if err != nil {
		t.Fatal(err)
	}
	name := randomName(t)
	unit := name + ".service"
	dir := filepath.Join(home, ".config", "systemd", "user")
	if err := os.MkdirAll(dir, 0o750); err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(dir, unit)
	body := "[Unit]\nDescription=LCM integration test (throwaway)\n\n[Service]\nExecStart=/bin/sleep 600\n"
	if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		_ = tool("systemctl", "--user", "stop", unit).Run()
		_ = os.Remove(path)
		_ = tool("systemctl", "--user", "daemon-reload").Run()
	})
	if out, err := tool("systemctl", "--user", "daemon-reload").CombinedOutput(); err != nil {
		t.Fatalf("daemon-reload: %v: %s", err, out)
	}

	s := svc(t, "type: systemd\n    unit: "+unit+"\n    scope: user")
	a, err := rt.NewRegistry(execx.New(), rt.Options{}).For(s)
	if err != nil {
		t.Fatal(err)
	}
	ctx := context.Background()
	status := func() rt.Status {
		st, err := a.Status(ctx, s)
		if err != nil {
			t.Fatalf("status: %v", err)
		}
		return st
	}

	if st := status(); st.State != rt.StateInactive {
		t.Fatalf("fresh unit: %+v", st)
	}
	if err := a.Start(ctx, s); err != nil {
		t.Fatal(err)
	}
	waitState(t, status, rt.StateActive)
	first := status().Detail["pid"]
	if first == "" {
		t.Fatalf("no pid in detail: %+v", status())
	}
	if err := a.Restart(ctx, s); err != nil {
		t.Fatal(err)
	}
	waitState(t, status, rt.StateActive)
	if second := status().Detail["pid"]; second == first {
		t.Fatalf("restart kept pid %s", first)
	}
	if err := a.Stop(ctx, s); err != nil {
		t.Fatal(err)
	}
	waitState(t, status, rt.StateInactive)
}

func TestRealDocker(t *testing.T) {
	if os.Getenv("LCM_IT_DOCKER") != "1" {
		t.Skip("set LCM_IT_DOCKER=1 to run against Docker")
	}
	if err := tool("docker", "version", "--format", "{{.Server.Version}}").Run(); err != nil {
		t.Skipf("docker is not accessible: %v", err)
	}
	image := os.Getenv("LCM_IT_DOCKER_IMAGE")
	if image == "" {
		image = "python:3.14-alpine"
	}
	// Never pull: the test must not depend on the network.
	if err := tool("docker", "image", "inspect", image).Run(); err != nil {
		t.Skipf("image %s is not present locally (set LCM_IT_DOCKER_IMAGE)", image)
	}
	name := randomName(t)
	t.Cleanup(func() { _ = tool("docker", "rm", "-f", name).Run() })
	if out, err := tool("docker", "run", "-d", "--init", "--name", name, "--entrypoint", "sleep", image, "600").CombinedOutput(); err != nil {
		t.Fatalf("docker run: %v: %s", err, out)
	}

	s := svc(t, "type: docker\n    container: "+name)
	a, err := rt.NewRegistry(execx.New(), rt.Options{}).For(s)
	if err != nil {
		t.Fatal(err)
	}
	ctx := context.Background()
	status := func() rt.Status {
		st, err := a.Status(ctx, s)
		if err != nil {
			t.Fatalf("status: %v", err)
		}
		return st
	}

	if st := status(); st.State != rt.StateActive || st.Detail["image"] != image {
		t.Fatalf("running container: %+v", st)
	}
	if err := a.Stop(ctx, s); err != nil {
		t.Fatal(err)
	}
	// Stopping with SIGTERM makes sleep exit with 143.
	if st := status(); st.State != rt.StateInactive && st.State != rt.StateFailed {
		t.Fatalf("stopped container: %+v", st)
	}
	if err := a.Start(ctx, s); err != nil {
		t.Fatal(err)
	}
	waitState(t, status, rt.StateActive)
	if err := a.Restart(ctx, s); err != nil {
		t.Fatal(err)
	}
	waitState(t, status, rt.StateActive)
	if err := tool("docker", "rm", "-f", name).Run(); err != nil {
		t.Fatal(err)
	}
	if _, err := a.Status(ctx, s); err == nil {
		t.Fatal("removed container must report an error")
	}
}
